import { describe, expect, it } from 'vitest'
import { readingSets, validateReadingSets } from './content'
import { draftId, finishAttempt, gradeAttempt, makeAttempt, secondsRemaining, updateAnswer } from './logic'

describe('ÖSD A1 özgün Lesen setleri', () => {
  it('iki eksiksiz 3 parçalı / 16 soruluk set içerir', () => {
    expect(readingSets).toHaveLength(2)
    expect(validateReadingSets()).toEqual([])
    expect(readingSets.map(s => s.questions.length)).toEqual([16,16])
  })
  it('cevap anahtarları 1-6, JA/NEIN biçimini kullanır', () => {
    for (const set of readingSets) for (const q of set.questions)
      expect(q.part === 2 ? ['JA','NEIN'] : ['1','2','3','4','5','6']).toContain(q.answer)
  })
})
describe('Lesen oturumu ve puan', () => {
  const set = readingSets[0]
  it('sınavı 25 dakika ile başlatır ve zaman farkıyla sürdürür', () => {
    const a = makeAttempt(set,'exam',1000000)
    expect(secondsRemaining(a,1000000)).toBe(1500)
    expect(secondsRemaining(a,1060000)).toBe(1440)
    expect(secondsRemaining(a,3000000)).toBe(0)
  })
  it('çalışma modunda süre sınırı yoktur', () => {
    const a = makeAttempt(set,'practice')
    expect(a.endsAt).toBeUndefined()
    expect(a.mode).toBe('practice')
  })
  it('gerçek doğru, yanlış ve yanıtsız soruları ayrı sayar', () => {
    let a = makeAttempt(set,'practice')
    const [first,second] = set.questions
    a = updateAnswer(a,first.id,first.answer)
    a = updateAnswer(a,second.id,'6')
    expect(gradeAttempt(a,set.questions)).toMatchObject({correct:1,wrong:1,unanswered:14,answered:2})
    const finished = finishAttempt(a,set.questions,'submitted',2500000)
    expect(finished.finishedAt).toBeTruthy()
    expect(finished.correctCount).toBe(1)
    expect(finished.answeredCount).toBe(2)
    expect(finished.questionCount).toBe(16)
    expect(finished.id).not.toBe(draftId(set.id,'practice'))
  })
  it('bir soru tekrar yanıtlandığında çift saymaz', () => {
    let a = makeAttempt(set,'practice')
    a = updateAnswer(a,set.questions[0].id,'6')
    a = updateAnswer(a,set.questions[0].id,set.questions[0].answer)
    expect(a.answers).toHaveLength(1)
    expect(gradeAttempt(a,set.questions).correct).toBe(1)
  })
})

import type { Answer } from '../../storage/models'
import type { ReadingQuestion, ReadingSet } from './content'

export type LesenMode = 'practice' | 'exam'
export interface LesenAttempt {
  id: string
  module: 'lesen'
  taskId: string
  mode: LesenMode
  startedAt: string
  updatedAt: string
  finishedAt?: string
  endsAt?: string
  completionReason?: 'submitted' | 'timeout'
  currentIndex: number
  flaggedQuestionIds: string[]
  answers: Answer[]
  answeredCount?: number
  correctCount?: number
  questionCount?: number
}

export const EXAM_SECONDS = 25 * 60
export const draftId = (setId: string, mode: LesenMode) => 'lesen:' + setId + ':' + mode + ':active'
export const selectedValue = (attempt: LesenAttempt, id: string) =>
  attempt.answers.find(answer => answer.questionId === id)?.value as string | undefined

export function makeAttempt(set: ReadingSet, mode: LesenMode, at: number = Date.now()): LesenAttempt {
  const stamp = new Date(at).toISOString()
  return {
    id: draftId(set.id, mode), module: 'lesen', taskId: set.id, mode, startedAt: stamp,
    updatedAt: stamp, endsAt: mode === 'exam' ? new Date(at + EXAM_SECONDS * 1000).toISOString() : undefined,
    currentIndex: 0, flaggedQuestionIds: [], answers: []
  }
}
export function updateAnswer(attempt: LesenAttempt, questionId: string, value: string): LesenAttempt {
  return {
    ...attempt,
    updatedAt: new Date().toISOString(),
    answers: [...attempt.answers.filter(answer => answer.questionId !== questionId), { questionId, value }]
  }
}
export function gradeAttempt(attempt: LesenAttempt, questions: ReadingQuestion[]) {
  const answered = questions.filter(q => !!selectedValue(attempt, q.id))
  const correct = answered.filter(q => selectedValue(attempt, q.id) === q.answer)
  const wrong = answered.filter(q => selectedValue(attempt, q.id) !== q.answer)
  return {
    correct: correct.length,
    wrong: wrong.length,
    unanswered: questions.length - answered.length,
    answered: answered.length,
    total: questions.length,
    wrongQuestionIds: wrong.map(q => q.id)
  }
}
export function finishAttempt(attempt: LesenAttempt, questions: ReadingQuestion[], reason: 'submitted' | 'timeout', at: number = Date.now()): LesenAttempt {
  const result = gradeAttempt(attempt, questions)
  return {
    ...attempt,
    id: 'lesen:' + attempt.taskId + ':' + attempt.mode + ':finished:' + at,
    updatedAt: new Date(at).toISOString(), finishedAt: new Date(at).toISOString(),
    completionReason: reason, answeredCount: result.answered, correctCount: result.correct,
    questionCount: result.total
  }
}
export function secondsRemaining(attempt: LesenAttempt, now: number = Date.now()): number {
  if (!attempt.endsAt || attempt.mode === 'practice' || attempt.finishedAt) return EXAM_SECONDS
  return Math.max(0, Math.ceil((new Date(attempt.endsAt).getTime() - now) / 1000))
}
export function formatSeconds(seconds: number): string {
  return String(Math.floor(seconds / 60)).padStart(2, '0') + ':' + String(seconds % 60).padStart(2, '0')
}

